// Kroscloud fork (ssog carve-out) — see FORK-CHANGES.md [ssog-1].
//
// The SOG decode (unpackPcSogs + its OffscreenCanvas WebGL2 decodeImage)
// MOVED VERBATIM out of pcsogs.ts so it can run inside the inline worker
// bundle (worker.ts `unpackSsogUnit`) without pulling three or SplatLoader:
// the only imports here are type-only SplatLoader/defines types and the pure
// encode helpers from packedEncode.ts. pcsogs.ts re-exports unpackPcSogs, so
// existing consumers (oldWorker.ts, SplatLoader) are unchanged.
//
// [prec-1] (kroscloud.48) `options.origin`: the streamed-SOG unit decode packs
// centres relative to the model's pack origin (fp16 precision far from the
// file origin). Every other caller passes no origin and gets the same words.
//
// This module must NEVER value-import three or SplatLoader.

import type { PcSogsJson, PcSogsV2Json } from "./SplatLoader";
import type { SplatEncoding } from "./defines";
import {
  computeMaxSplats,
  encodeSh1Rgb,
  encodeSh2Rgb,
  encodeSh3Rgb,
  setPackedSplatCenter,
  setPackedSplatQuat,
  setPackedSplatRgba,
  setPackedSplatScales,
} from "./packedEncode";

export type DecodedImage = { rgba: Uint8Array; width: number; height: number };

export async function unpackPcSogs(
  json: PcSogsJson | PcSogsV2Json,
  extraFiles: Record<string, ArrayBuffer>,
  splatEncoding: SplatEncoding,
  options?: {
    /**
     * [ssog-22] decoded shared SH palette (shN_centroids image) for units that
     * carry labels only (`json.shN.palette` set, one file in `shN.files`).
     */
    centroidsImage?: Promise<DecodedImage> | DecodedImage;
    /**
     * [prec-1] pack origin o (file frame): every centre is packed as
     * fp16(c - o) and the consumer re-adds o (SsogSplats.centerOrigin, folded
     * into the mesh transform). Absent = the words exactly as before.
     */
    origin?: readonly [number, number, number];
  },
): Promise<{
  packedArray: Uint32Array;
  numSplats: number;
  extra: Record<string, unknown>;
}> {
  const isVersion2 = "version" in json;

  if (!isVersion2 && json.quats.encoding !== "quaternion_packed") {
    throw new Error("Unsupported quaternion encoding");
  }

  const numSplats = isVersion2 ? json.count : json.means.shape[0];
  const maxSplats = computeMaxSplats(numSplats);
  const packedArray = new Uint32Array(maxSplats * 4);
  const extra: Record<string, unknown> = {};

  // [prec-1] x - (+0) is x bit for bit (-0 included), so without an origin
  // every centre word is the one this decoder always wrote.
  const ox = options?.origin ? options.origin[0] || 0 : 0;
  const oy = options?.origin ? options.origin[1] || 0 : 0;
  const oz = options?.origin ? options.origin[2] || 0 : 0;

  const meansPromise = Promise.all([
    decodeImageRgba(extraFiles[json.means.files[0]]),
    decodeImageRgba(extraFiles[json.means.files[1]]),
  ]).then((means) => {
    for (let i = 0; i < numSplats; ++i) {
      const i4 = i * 4;
      const fx = (means[0][i4 + 0] + (means[1][i4 + 0] << 8)) / 65535;
      const fy = (means[0][i4 + 1] + (means[1][i4 + 1] << 8)) / 65535;
      const fz = (means[0][i4 + 2] + (means[1][i4 + 2] << 8)) / 65535;
      let x =
        json.means.mins[0] + (json.means.maxs[0] - json.means.mins[0]) * fx;
      let y =
        json.means.mins[1] + (json.means.maxs[1] - json.means.mins[1]) * fy;
      let z =
        json.means.mins[2] + (json.means.maxs[2] - json.means.mins[2]) * fz;
      x = Math.sign(x) * (Math.exp(Math.abs(x)) - 1);
      y = Math.sign(y) * (Math.exp(Math.abs(y)) - 1);
      z = Math.sign(z) * (Math.exp(Math.abs(z)) - 1);
      setPackedSplatCenter(packedArray, i, x - ox, y - oy, z - oz);
    }
  });

  const scalesPromise = decodeImageRgba(extraFiles[json.scales.files[0]]).then(
    (scales) => {
      let xLookup: number[];
      let yLookup: number[];
      let zLookup: number[];

      if (isVersion2) {
        xLookup =
          yLookup =
          zLookup =
            json.scales.codebook.map((x) => Math.exp(x));
      } else {
        xLookup = new Array(256)
          .fill(0)
          .map(
            (_, i) =>
              json.scales.mins[0] +
              (json.scales.maxs[0] - json.scales.mins[0]) * (i / 255),
          )
          .map((x) => Math.exp(x));
        yLookup = new Array(256)
          .fill(0)
          .map(
            (_, i) =>
              json.scales.mins[1] +
              (json.scales.maxs[1] - json.scales.mins[1]) * (i / 255),
          )
          .map((x) => Math.exp(x));
        zLookup = new Array(256)
          .fill(0)
          .map(
            (_, i) =>
              json.scales.mins[2] +
              (json.scales.maxs[2] - json.scales.mins[2]) * (i / 255),
          )
          .map((x) => Math.exp(x));
      }

      for (let i = 0; i < numSplats; ++i) {
        const i4 = i * 4;
        setPackedSplatScales(
          packedArray,
          i,
          xLookup[scales[i4 + 0]],
          yLookup[scales[i4 + 1]],
          zLookup[scales[i4 + 2]],
          splatEncoding,
        );
      }
    },
  );

  const quatsPromise = decodeImageRgba(extraFiles[json.quats.files[0]]).then(
    (quats) => {
      const SQRT2 = Math.sqrt(2);
      const lookup = new Array(256)
        .fill(0)
        .map((_, i) => (i / 255 - 0.5) * SQRT2);

      for (let i = 0; i < numSplats; ++i) {
        const i4 = i * 4;
        const r0 = lookup[quats[i4 + 0]];
        const r1 = lookup[quats[i4 + 1]];
        const r2 = lookup[quats[i4 + 2]];
        const rr = Math.sqrt(Math.max(0, 1.0 - r0 * r0 - r1 * r1 - r2 * r2));
        const rOrder = quats[i4 + 3] - 252;
        const quatX = rOrder === 0 ? r0 : rOrder === 1 ? rr : r1;
        const quatY = rOrder <= 1 ? r1 : rOrder === 2 ? rr : r2;
        const quatZ = rOrder <= 2 ? r2 : rr;
        const quatW = rOrder === 0 ? rr : r0;
        setPackedSplatQuat(packedArray, i, quatX, quatY, quatZ, quatW);
      }
    },
  );
  const sh0Promise = decodeImageRgba(extraFiles[json.sh0.files[0]]).then(
    (sh0) => {
      const SH_C0 = 0.28209479177387814;
      let rLookup: number[];
      let gLookup: number[];
      let bLookup: number[];
      let aLookup: number[];

      if (isVersion2) {
        rLookup =
          gLookup =
          bLookup =
            json.sh0.codebook.map((x) => SH_C0 * x + 0.5);
        aLookup = new Array(256).fill(0).map((_, i) => i / 255);
      } else {
        rLookup = new Array(256)
          .fill(0)
          .map(
            (_, i) =>
              json.sh0.mins[0] +
              (json.sh0.maxs[0] - json.sh0.mins[0]) * (i / 255),
          )
          .map((x) => SH_C0 * x + 0.5);
        gLookup = new Array(256)
          .fill(0)
          .map(
            (_, i) =>
              json.sh0.mins[1] +
              (json.sh0.maxs[1] - json.sh0.mins[1]) * (i / 255),
          )
          .map((x) => SH_C0 * x + 0.5);
        bLookup = new Array(256)
          .fill(0)
          .map(
            (_, i) =>
              json.sh0.mins[2] +
              (json.sh0.maxs[2] - json.sh0.mins[2]) * (i / 255),
          )
          .map((x) => SH_C0 * x + 0.5);
        aLookup = new Array(256)
          .fill(0)
          .map(
            (_, i) =>
              json.sh0.mins[3] +
              (json.sh0.maxs[3] - json.sh0.mins[3]) * (i / 255),
          )
          .map((x) => 1.0 / (1.0 + Math.exp(-x)));
      }

      for (let i = 0; i < numSplats; ++i) {
        const i4 = i * 4;
        setPackedSplatRgba(
          packedArray,
          i,
          rLookup[sh0[i4 + 0]],
          gLookup[sh0[i4 + 1]],
          bLookup[sh0[i4 + 2]],
          aLookup[sh0[i4 + 3]],
          splatEncoding,
        );
      }
    },
  );

  const promises = [meansPromise, scalesPromise, quatsPromise, sh0Promise];
  if (json.shN) {
    const useSH3 = isVersion2
      ? json.shN.bands >= 3
      : json.shN.shape[1] >= 48 - 3;
    const useSH2 = isVersion2
      ? json.shN.bands >= 2
      : json.shN.shape[1] >= 27 - 3;
    const useSH1 = isVersion2
      ? json.shN.bands >= 1
      : json.shN.shape[1] >= 12 - 3;

    if (useSH1) extra.sh1 = new Uint32Array(numSplats * 2);
    if (useSH2) extra.sh2 = new Uint32Array(numSplats * 4);
    if (useSH3) extra.sh3 = new Uint32Array(numSplats * 4);

    const sh1 = new Float32Array(9);
    const sh2 = new Float32Array(15);
    const sh3 = new Float32Array(21);

    const shN = json.shN;
    // [ssog-22] Two unit shapes: classic units ship [centroids, labels]; units
    // written against a scene-level palette ship [labels] only and the caller
    // hands in the decoded shared palette image (SsogUnitCache fetches it once
    // per scene, the worker decodes it once per worker). The labels plane is
    // always the LAST file; the lookup/stride code below is shape-agnostic.
    const shFiles = shN.files;
    const labelsFile = shFiles[shFiles.length - 1];
    let centroidsPromise: Promise<DecodedImage>;
    if (options?.centroidsImage) {
      centroidsPromise = Promise.resolve(options.centroidsImage);
    } else if (shFiles.length >= 2) {
      centroidsPromise = decodeImage(extraFiles[shFiles[0]]);
    } else {
      throw new Error(
        "SOG unit references a shared SH palette but no palette image was supplied",
      );
    }
    const shNPromise = Promise.all([
      centroidsPromise,
      decodeImage(extraFiles[labelsFile]),
    ]).then(([centroids, labels]) => {
      const lookup =
        "codebook" in shN
          ? shN.codebook
          : new Array(256)
              .fill(0)
              .map((_, i) => shN.mins + (shN.maxs - shN.mins) * (i / 255));

      // [ssog-10] Centroid stride = coefficients per centroid. splat-transform
      // >= 3.x packs 64 centroids per row at `64 * shCoeffs` px wide (3 / 8 /
      // 15 for bands 1 / 2 / 3); upstream Spark hard-codes 15, which reads
      // garbage for SH1/SH2 files (every lookup lands on the wrong centroid
      // - field-hit on an SH2 scene as washed-out colour + blue/white
      // blotches). The image width is the authoritative source: writers have
      // always used 64 columns, so width / 64 is the stride for every vintage.
      const shStride = Math.max(1, Math.floor(centroids.width / 64));

      for (let i = 0; i < numSplats; ++i) {
        const i4 = i * 4;
        const label = labels.rgba[i4 + 0] + (labels.rgba[i4 + 1] << 8);
        const col = (label & 63) * shStride;
        const row = label >>> 6;
        const offset = row * centroids.width + col;

        for (let d = 0; d < 3; ++d) {
          if (useSH1) {
            for (let k = 0; k < 3; ++k) {
              sh1[k * 3 + d] = lookup[centroids.rgba[(offset + k) * 4 + d]];
            }
          }

          if (useSH2) {
            for (let k = 0; k < 5; ++k) {
              sh2[k * 3 + d] = lookup[centroids.rgba[(offset + 3 + k) * 4 + d]];
            }
          }

          if (useSH3) {
            for (let k = 0; k < 7; ++k) {
              sh3[k * 3 + d] = lookup[centroids.rgba[(offset + 8 + k) * 4 + d]];
            }
          }
        }

        if (useSH1)
          encodeSh1Rgb(extra.sh1 as Uint32Array, i, sh1, splatEncoding);
        if (useSH2)
          encodeSh2Rgb(extra.sh2 as Uint32Array, i, sh2, splatEncoding);
        if (useSH3)
          encodeSh3Rgb(extra.sh3 as Uint32Array, i, sh3, splatEncoding);
      }
    });
    promises.push(shNPromise);
  }

  await Promise.all(promises);

  return { packedArray, numSplats, extra };
}

// WebGL context for reading raw pixel data of WebP images
let offscreenGlContext: WebGL2RenderingContext | null = null;

export async function decodeImage(fileBytes: ArrayBuffer) {
  if (!offscreenGlContext) {
    const canvas = new OffscreenCanvas(1, 1);
    offscreenGlContext = canvas.getContext("webgl2");
    if (!offscreenGlContext) {
      throw new Error("Failed to create WebGL2 context");
    }
  }

  const imageBlob = new Blob([fileBytes]);
  const bitmap = await createImageBitmap(imageBlob, {
    premultiplyAlpha: "none",
  });

  const gl = offscreenGlContext;
  const texture = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, bitmap);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);

  const framebuffer = gl.createFramebuffer();
  gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
  gl.framebufferTexture2D(
    gl.FRAMEBUFFER,
    gl.COLOR_ATTACHMENT0,
    gl.TEXTURE_2D,
    texture,
    0,
  );

  const data = new Uint8Array(bitmap.width * bitmap.height * 4);
  gl.readPixels(
    0,
    0,
    bitmap.width,
    bitmap.height,
    gl.RGBA,
    gl.UNSIGNED_BYTE,
    data,
  );

  gl.deleteTexture(texture);
  gl.deleteFramebuffer(framebuffer);

  return { rgba: data, width: bitmap.width, height: bitmap.height };
}

export async function decodeImageRgba(fileBytes: ArrayBuffer) {
  const { rgba } = await decodeImage(fileBytes);
  return rgba;
}
